import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
maps = []


def make_map(id, title, task, focus, routes, documents, codes):
    item = dict(id=id, title=title, task=task, focus=focus,
                routes=[dict(id=k, title=v) for k, v in routes],
                documents=documents, standards=codes, nodes=[], claims=[])
    maps.append(item)
    return item


def node(m, id, title, codes, question, expected):
    m['nodes'].append(dict(id=id, title=title, standards=codes,
                           question=question, expected=expected))


def claim(m, a, b, kind, routes, reason, conditions, check, question, expected,
          alternative, group=None, relation_ids=(), research=False):
    m['claims'].append(dict(
        id=f"{m['id']}-{len(m['claims'])+1:02d}", source=a, target=b,
        kind=kind, routes=routes, rationale=reason, conditions=conditions,
        mathematical_check=check, probe=dict(question=question, expected=expected),
        alternative=alternative, condition_group=group,
        original_relation_ids=list(relation_ids),
        evidence_kind='수학적 분석과 과제별 조건의 자체 점검',
        research_context=['WILKINS_NORTON_2018'] if research else [],
        status='초안 · 수학적 자체 점검', independent_review=False,
        student_validated=False))


